-- Final assertions.
DO $$
DECLARE renamed int; long_names int; orphaned int;
BEGIN
  SELECT count(*) INTO renamed FROM public.topics t
   WHERE t.metadata ? 'full_description';
  IF renamed < 426 THEN
    RAISE EXCEPTION 'expected at least 426 renamed rows, got %', renamed;
  END IF;

  SELECT count(*) INTO long_names FROM public.topics t
    JOIN public.subjects s ON s.id = t.subject_id
   WHERE s.name IN ('General Studies I','General Studies II',
                    'General Studies III','General Studies IV')
     AND t.level = 'microtopic' AND t.is_active AND length(t.name) > 80;
  IF long_names > 0 THEN
    RAISE EXCEPTION '% active Mains microtopic(s) still exceed 80 chars', long_names;
  END IF;

  SELECT count(*) INTO orphaned FROM public.topics
   WHERE id IN ('9f4e8c3c-5848-426d-b94d-bd0dcd61ceee'::uuid,'e985eec7-1892-498f-a043-41798b1e1480'::uuid,'fbe18f61-cac9-41a3-88f2-c0aa78d57802'::uuid,'a3284754-ee69-4931-8653-2f98e7ebd76a'::uuid,'d0b5594e-8416-47b3-b06b-13c227b72421'::uuid,'27a388e4-9648-4da4-8328-d0aa92b7d3af'::uuid,'d19b8f09-c461-495e-b88c-ea96b791f9c0'::uuid,'da3a5849-aa34-4290-9ec4-a4c9937c9f17'::uuid,'08be0cf6-778c-42c5-88d8-0c941f0cadd2'::uuid,'c2b5c010-2390-41a4-9d4b-ada83e95c788'::uuid,'8255e2a0-76e2-4cfd-b3ff-fcb8af87baae'::uuid,'e32b3e50-d206-402a-a2cf-a623b7544841'::uuid,'2bb22d62-cc65-4ee2-8477-9b0f334d53e1'::uuid,'d2730696-4878-4a11-a806-9955b693e5b6'::uuid,'bf975128-6ca9-4674-9e90-f15afe4250fc'::uuid,'a46877f5-18ba-4125-ab77-7799541bc8cb'::uuid,'64e81c50-6b2b-468c-b940-9c7a08a4cc61'::uuid,'da6e368f-bf7d-4b84-b1e0-931ac30de4ed'::uuid) AND is_active;
  IF orphaned > 0 THEN
    RAISE EXCEPTION '% orphan(s) still active', orphaned;
  END IF;
END $$;

